package br.com.mariacarmela.receitas;
import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.net.Uri;
import android.os.Build;
import android.provider.Settings;
import android.widget.Toast;
import org.json.*;
import java.io.*;
import java.net.*;
import java.security.MessageDigest;
import java.util.*;

final class AppUpdater {
 private final Activity activity;
 private volatile boolean busy=false;
 private boolean waitingPermission=false;
 private boolean foreground=false;
 private volatile boolean promptPending=false;
 private AlertDialog updateDialog;
 private static final String RELEASES="https://api.github.com/repos/palomagarcia38-create/RECEITAS-ON-A/releases/latest";
 AppUpdater(Activity activity){this.activity=activity;}
 private void ui(Runnable task){activity.runOnUiThread(()->{if(!activity.isFinishing()&&!activity.isDestroyed())task.run();});}
 void check(boolean manual){if(busy||promptPending)return;busy=true;if(manual)Toast.makeText(activity,"Procurando atualização…",Toast.LENGTH_SHORT).show();new Thread(()->{try{JSONObject release=new JSONObject(read(RELEASES,512*1024));JSONArray assets=release.getJSONArray("assets");String metadata="";for(int i=0;i<assets.length();i++){JSONObject asset=assets.getJSONObject(i);if("update.json".equals(asset.getString("name")))metadata=asset.getString("browser_download_url");}if(metadata.isEmpty())throw new IOException("A atualização ainda está sendo preparada.");JSONObject info=new JSONObject(read(metadata,32768));long current=version(activity.getPackageManager().getPackageInfo(activity.getPackageName(),0));if(info.getLong("versionCode")<=current){if(manual)ui(()->Toast.makeText(activity,"Seu app está atualizado.",Toast.LENGTH_LONG).show());return;}if(!activity.getPackageName().equals(info.getString("packageId")))throw new IOException("Atualização incompatível.");showUpdate(info);}catch(Exception e){if(manual)ui(()->Toast.makeText(activity,"Não foi possível verificar agora. "+e.getMessage(),Toast.LENGTH_LONG).show());}finally{busy=false;}}).start();}

 private void showUpdate(JSONObject info){promptPending=true;ui(()->{if(!foreground){promptPending=false;return;}updateDialog=new AlertDialog.Builder(activity).setTitle("Nova versão disponível").setMessage("Receitas Onça "+info.optString("versionName")+"\n\nBaixe a atualização e confirme a instalação no Android. Suas receitas serão mantidas.").setNegativeButton("Depois",null).setPositiveButton("Baixar atualização",(d,w)->download(info)).create();updateDialog.setOnDismissListener(d->{promptPending=false;updateDialog=null;});updateDialog.show();});}
 private HttpURLConnection connection(String value)throws Exception{return connection(value,0);}
 private HttpURLConnection connection(String value,int redirects)throws Exception{if(redirects>5)throw new IOException("Muitos redirecionamentos.");URL url=new URL(value);if(!"https".equals(url.getProtocol())||!(url.getHost().equals("api.github.com")||url.getHost().equals("github.com")||url.getHost().equals("release-assets.githubusercontent.com")||url.getHost().equals("objects.githubusercontent.com")))throw new IOException("Endereço de atualização inválido.");HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestProperty("User-Agent","Receitas-Onca-Android");c.setUseCaches(false);c.setRequestProperty("Cache-Control","no-cache");c.setInstanceFollowRedirects(false);int status=c.getResponseCode();if(status>=300&&status<400){String location=c.getHeaderField("Location");c.disconnect();if(location==null)throw new IOException("Download indisponível.");return connection(new URL(url,location).toString(),redirects+1);}if(status!=200){c.disconnect();throw new IOException("Servidor indisponível ("+status+").");}return c;}
 private String read(String url,int max)throws Exception{HttpURLConnection c=connection(url);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("Resposta muito grande.");out.write(b,0,n);}return out.toString("UTF-8");}finally{c.disconnect();}}
 private void download(JSONObject info){if(busy)return;busy=true;ProgressDialog progress=new ProgressDialog(activity);progress.setTitle("Baixando atualização");progress.setMessage("Aguarde. Suas receitas continuam no aparelho.");progress.setProgressStyle(ProgressDialog.STYLE_HORIZONTAL);progress.setMax(100);progress.setCancelable(false);progress.show();new Thread(()->{File part=new File(activity.getCacheDir(),"update.part");File apk=new File(activity.getCacheDir(),"update.apk");try{HttpURLConnection c=connection(info.getString("apkUrl"));MessageDigest digest=MessageDigest.getInstance("SHA-256");long total=0,expected=c.getContentLengthLong();try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(part)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){total+=n;if(total>100L*1024*1024)throw new IOException("Arquivo maior que o permitido.");digest.update(b,0,n);out.write(b,0,n);int percent=expected>0?(int)(total*100/expected):0;ui(()->progress.setProgress(percent));}}finally{c.disconnect();}StringBuilder hash=new StringBuilder();for(byte b:digest.digest())hash.append(String.format(Locale.ROOT,"%02x",b&255));if(!hash.toString().equalsIgnoreCase(info.getString("sha256")))throw new IOException("O arquivo não passou na verificação. Tente novamente.");validate(part,info.getLong("versionCode"));if(apk.exists()&&!apk.delete())throw new IOException("Não foi possível preparar o arquivo.");if(!part.renameTo(apk))throw new IOException("Não foi possível salvar a atualização.");ui(()->{progress.dismiss();install();});}catch(Exception e){part.delete();ui(()->{progress.dismiss();new AlertDialog.Builder(activity).setTitle("Atualização não instalada").setMessage(e.getMessage()+"\n\nNão desinstale o aplicativo: suas receitas continuam salvas.").setPositiveButton("Entendi",null).show();});}finally{busy=false;}}).start();}
 private long version(PackageInfo p){return Build.VERSION.SDK_INT>=28?p.getLongVersionCode():p.versionCode;}
 private Signature[] signatures(PackageInfo p){return Build.VERSION.SDK_INT>=28?p.signingInfo.getApkContentsSigners():p.signatures;}
 private void validate(File apk,long expected)throws Exception{int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageManager pm=activity.getPackageManager();PackageInfo candidate=pm.getPackageArchiveInfo(apk.getAbsolutePath(),flags),installed=pm.getPackageInfo(activity.getPackageName(),flags);if(candidate==null||!activity.getPackageName().equals(candidate.packageName)||version(candidate)!=expected||version(candidate)<=version(installed))throw new IOException("Versão de atualização inválida.");Signature[] a=signatures(candidate),b=signatures(installed);if(a==null||b==null||a.length!=b.length||!new HashSet<>(Arrays.asList(a)).equals(new HashSet<>(Arrays.asList(b))))throw new IOException("Esta versão tem uma assinatura diferente. A migração precisa ser feita antes da atualização.");}
 void resume(){foreground=true;if(waitingPermission){waitingPermission=false;if(activity.getPackageManager().canRequestPackageInstalls()){install();return;}}check(false);}
 void pause(){foreground=false;}
 void install(){File apk=new File(activity.getCacheDir(),"update.apk");if(!apk.exists()){check(true);return;}try{if(!activity.getPackageManager().canRequestPackageInstalls()){new AlertDialog.Builder(activity).setTitle("Permitir atualização").setMessage("Na próxima tela, permita que Receitas Onça instale atualizações. Depois volte ao app.").setNegativeButton("Depois",null).setPositiveButton("Abrir configuração",(d,w)->{waitingPermission=true;activity.startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName())));}).show();return;}Intent intent=new Intent(Intent.ACTION_VIEW);intent.setDataAndType(Uri.parse("content://"+activity.getPackageName()+".updates/update.apk"),"application/vnd.android.package-archive");intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);activity.startActivity(intent);}catch(Exception e){Toast.makeText(activity,"Não foi possível abrir a instalação.",Toast.LENGTH_LONG).show();}}
}
